function rebuildAddresses(s: string): string[] {
  const ok = (p: string) => p.length > 0 && p.length <= 3 && (p === "0" || p[0] !== "0") && Number(p) <= 255;
  const out: string[] = [];
  const n = s.length;
  for (let a = 1; a <= 3; a++)
    for (let b = a + 1; b <= a + 3; b++)
      for (let c = b + 1; c <= b + 3; c++) {
        if (c >= n || n - c > 3) continue;
        const parts = [s.slice(0, a), s.slice(a, b), s.slice(b, c), s.slice(c)];
        if (parts.every(ok)) out.push(parts.join("."));
      }
  return out;
}

