class Solution:
    def rebuildAddresses(self, s: str) -> List[str]:
        def ok(p):
            return 0 < len(p) <= 3 and (p == "0" or p[0] != "0") and int(p) <= 255

        n, out = len(s), []
        for a in range(1, 4):
            for b in range(a + 1, a + 4):
                for c in range(b + 1, b + 4):
                    if c >= n or n - c > 3:
                        continue
                    parts = [s[:a], s[a:b], s[b:c], s[c:]]
                    if all(ok(p) for p in parts):
                        out.append(".".join(parts))
        return out

