function rebuildAddresses(s: string): string[] {
  const out: string[] = [], parts: string[] = [];
  const go = (start: number) => {
    const left = 4 - parts.length, rest = s.length - start;
    if (left === 0) {
      if (rest === 0) out.push(parts.join("."));
      return;
    }
    if (rest < left || rest > 3 * left) return;
    for (let len = 1; len <= 3 && len <= rest; len++) {
      const p = s.slice(start, start + len);
      if (len > 1 && p[0] === "0") break; // longer pieces keep the leading zero
      if (Number(p) > 255) break;
      parts.push(p);
      go(start + len);
      parts.pop();
    }
  };
  go(0);
  return out;
}

