            if rest < left or rest > 3 * left:
                return
            for length in range(1, min(3, rest) + 1):
                p = s[start:start + length]
                if length > 1 and p[0] == "0":
                    break  # longer pieces keep the leading zero
                if int(p) > 255:
                    break
                parts.append(p)
                go(start + length)
                parts.pop()

        go(0)
        return out

